 async function loadChannels(orgId){
  const {data,error}=await supabase.from('connect_channels').select('*').eq('organization_id',orgId).order('created_at',{ascending:true});if(error)throw error;
  setChannels(data||[]);const preferred=(data||[]).find(c=>c.id===channel?.id)||(data||[]).find(c=>c.name==='general')||(data||[])[0]||null;setChannel(preferred);
 }
 useEffect(()=>{if(!org||!channel)return;loadMessages();loadFiles();loadMembers();const ch=supabase.channel('connect-'+channel.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'connect_messages',filter:'channel_id=eq.'+channel.id},payload=>{loadMessages();const msg=payload.new;if(msg?.sender_id!==session?.user?.id&&typeof Notification!=='undefined'&&Notification.permission==='granted'){try{new Notification('Nouveau message · #'+channel.name,{body:String(msg.body||'Nouveau message').slice(0,140),tag:'connect-'+msg.id})}catch{}}}).subscribe();return()=>{supabase.removeChannel(ch)}},[org?.id,channel?.id]);
 useEffect(()=>{if(!channel||!session)return;let active=true;(async()=>{const [r,p]=await Promise.all([supabase.from('connect_message_reactions').select('*').in('message_id',messages.map(m=>m.id).filter(Boolean)),supabase.from('connect_message_pins').select('*').eq('channel_id',channel.id)]);if(active){if(!r.error)setReactions(r.data||[]);if(!p.error)setPinnedMessages(p.data||[])}})();return()=>{active=false}},[channel?.id,messages.map(m=>m.id).join(',')]);
 useEffect(()=>{if(!session||!org)return;loadNotifications()},[session?.user?.id,org?.id]);
 useEffect(()=>{if(channel&&session){try{const key='connect_draft:'+session.user.id+':'+channel.id;setDraft(localStorage.getItem(key)||'')}catch{}}},[channel?.id,session?.user?.id]);
 useEffect(()=>{if(!channel||!session)return;try{const key='connect_draft:'+session.user.id+':'+channel.id;if(draft)localStorage.setItem(key,draft);else localStorage.removeItem(key)}catch{}},[draft,channel?.id,session?.user?.id]);
 useEffect(()=>{if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});},[]);
 useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth'})},[messages]);
 useEffect(()=>{const onKeyDown=e=>{const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='k'){e.preventDefault();searchInput.current?.focus();searchInput.current?.select()}if(e.key==='Escape'){if(modal)setModal('');else if(channelInfoOpen)setChannelInfoOpen(false);else if(mobileNavOpen)setMobileNavOpen(false);else if(document.activeElement===searchInput.current){setSearch('');searchInput.current?.blur()}}if((e.ctrlKey||e.metaKey)&&e.shiftKey&&key==='n'){e.preventDefault();setNewChannel('');setNewDesc('');setModal('channel')}};window.addEventListener('keydown',onKeyDown);return()=>window.removeEventListener('keydown',onKeyDown)},[modal,channelInfoOpen,mobileNavOpen]);
 useEffect(()=>{if(!session)return;const params=new URLSearchParams(location.search);const hashParams=new URLSearchParams(location.hash.startsWith('#')?location.hash.slice(1):location.hash);const q=params.get('invite')||hashParams.get('invite');if(!q)return;const cleanUrl=()=>{params.delete('invite');hashParams.delete('invite');const query=params.toString();const hash=hashParams.toString();history.replaceState({},'',location.pathname+(query?'?'+query:'')+(hash?'#'+hash:''))};let accepted=[];try{accepted=JSON.parse(localStorage.getItem('connect_accepted_invites')||'[]')}catch{}if(accepted.includes(q)){cleanUrl();setModal(current=>current==='accept'?'':current);return;}if(session.user?.email){const acceptedEmail=localStorage.getItem('connect_invite_accepted_email:'+q);if(acceptedEmail===session.user.email.toLowerCase()){cleanUrl();setModal(current=>current==='accept'?'':current);return;}}setSection('members');setModal('accept')},[session?.user?.id,session?.user?.email,org?.id]);
 async function loadMessages(){if(!channel)return;const {data,error}=await supabase.from('connect_messages').select('*').eq('channel_id',channel.id).is('deleted_at',null).order('created_at',{ascending:true}).limit(300);if(error){say(friendly(error));return}setMessages(data||[])}
 async function loadMembers(){if(!org)return;const {data,error}=await supabase.from('connect_members').select('organization_id,user_id,role,joined_at').eq('organization_id',org.id).order('joined_at');if(error){say(friendly(error));return}const ids=(data||[]).map(m=>m.user_id);let profiles=[];if(ids.length){const r=await supabase.from('connect_profiles').select('user_id,display_name,avatar_url').in('user_id',ids);profiles=r.data||[]}setMembers((data||[]).map(m=>({...m,profile:profiles.find(p=>p.user_id===m.user_id)})))}
 async function loadMeetings(orgId){const {data,error}=await supabase.from('connect_meetings').select('*').eq('organization_id',orgId).order('created_at',{ascending:false});if(error){say(friendly(error));return}setMeetings(data||[])}
 async function createMeeting(e){e.preventDefault();if(!org)return;setBusy(true);try{const slug=(org.slug||org.name||'infotelcom').toLowerCase().replace(/[^a-z0-9-]/g,'-').replace(/-+/g,'-').slice(0,28);const room='INFOTELCOM-'+slug+'-'+crypto.randomUUID().replace(/-/g,'').slice(0,12);const url='https://meet.jit.si/'+room;const payload={organization_id:org.id,created_by:session.user.id,title:meetingTitle.trim(),room_name:room,meeting_url:url,scheduled_at:meetingTime?new Date(meetingTime).toISOString():null};const {error}=await supabase.from('connect_meetings').insert(payload);if(error)throw error;await loadMeetings(org.id);setModal('');setMeetingTitle('Réunion INFOTELCOM');setMeetingTime('');setSection('calls');try{await navigator.clipboard.writeText(url)}catch{}say('Salle créée. Important : sur meet.jit.si, connecte-toi à Jitsi pour devenir modérateur avant de faire entrer les invités.')}catch(e){say(friendly(e))}finally{setBusy(false)}}
 async function copyMeeting(url){try{await navigator.clipboard.writeText(url);say('Lien de visioconférence copié. Tu peux l’envoyer aux participants.')}catch{say(url)}}
 async function deleteMeeting(meeting){if(!confirm('Supprimer cette réunion de la liste ? Le lien externe ne sera pas désactivé.'))return;const {error}=await supabase.from('connect_meetings').delete().eq('id',meeting.id);if(error)say(friendly(error));else{await loadMeetings(org.id);say('Réunion retirée de la liste. Le lien externe reste utilisable.')}}
 async function loadFiles(){if(!org)return;const {data,error}=await supabase.storage.from('connect-files').list(org.id,{limit:100,sortBy:{column:'created_at',order:'desc'}});if(error){say(friendly(error));return}setFiles(data||[])}
 async function authSubmit(e){e.preventDefault();setBusy(true);setNotice('');try{if(authMode==='signup'){const {data,error}=await supabase.auth.signUp({email,password,options:{data:{display_name:displayName},emailRedirectTo:location.origin}});if(error)throw error;if(!data.session)say('Compte créé. Vérifie ta boîte e-mail pour confirmer ton adresse avant de te connecter.');else say('Compte créé.')}else{const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error}}catch(e){say(friendly(e))}finally{setBusy(false)}}
